solution.solution.cpp:
class Thermostat
{
public:
    void setTarget(double degrees)
    {
        if (degrees < 10.0) degrees = 10.0;
        if (degrees > 30.0) degrees = 30.0;
        m_target = degrees;
    }

    void nudge(double change) { setTarget(m_target + change); }

    double target() const { return m_target; }

private:
    double m_target{ 20.0 };
};

unitTests:
TEST("starts at 20") { Thermostat t{}; CHECK_NEAR(t.target(), 20.0, 1e-9); }
TEST("accepts values in range") { Thermostat t{}; t.setTarget(24.5); CHECK_NEAR(t.target(), 24.5, 1e-9); }
TEST("refuses to go out of range") { Thermostat t{}; t.setTarget(99.0); CHECK_NEAR(t.target(), 30.0, 1e-9); t.setTarget(-40.0); CHECK_NEAR(t.target(), 10.0, 1e-9); }
TEST("nudge stays in range too") { Thermostat t{}; t.nudge(3.0); CHECK_NEAR(t.target(), 23.0, 1e-9); t.nudge(50.0); CHECK_NEAR(t.target(), 30.0, 1e-9); t.nudge(-100.0); CHECK_NEAR(t.target(), 10.0, 1e-9); }

